// AppendScalars appends the JSON encoding of v to dst.
func AppendScalars(dst []byte, v *Scalars) ([]byte, error) {
	return v.odjsonAppend(dst, odjsonrt.ModeHTML)
}

// odjsonSizeScalars sizes the buffer MarshalScalars allocates.
var odjsonSizeScalars odjsonrt.SizeHint

// MarshalScalars returns the JSON encoding of v.
func MarshalScalars(v *Scalars) ([]byte, error) {
	buf, err := v.odjsonAppend(odjsonSizeScalars.New(), odjsonrt.ModeHTML)
	if err != nil {
		return nil, err
	}
	odjsonSizeScalars.Record(buf)
	return buf, nil
}

// UnmarshalScalars decodes the JSON document data into v.
func UnmarshalScalars(data []byte, v *Scalars) error {
	// The cache plays the part of encoding/json/v2's string cache: a
	// value that recurs in the document is allocated once.
	sc := odjsonrt.GetStringCache()
	p, err := v.odjsonParse(data, odjsonrt.SkipSpace(data, 0), sc)
	odjsonrt.PutStringCache(sc)
	if err != nil {
		return err
	}
	return odjsonrt.EndOfDocument(data, p)
}

